{"content": "/* Variables CSS */
:root {
    --primary-color: #2563eb;
    --success-color: #10b981;
    --danger-color: #ef4444;
    --warning-color: #f59e0b;
    --dark-bg: #1e293b;
    --darker-bg: #0f172a;
    --light-text: #f1f5f9;
    --gray-text: #94a3b8;
    --available-color: #22c55e;
    --occupied-color: #ef4444;
    --selected-color: #3b82f6;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background: linear-gradient(135deg, var(--darker-bg) 0%, var(--dark-bg) 100%);
    color: var(--light-text);
    min-height: 100vh;
}

.container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 20px;
}

/* Header */
.header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 20px;
    background: rgba(30, 41, 59, 0.8);
    border-radius: 10px;
    margin-bottom: 30px;
    backdrop-filter: blur(10px);
}

.header h1 {
    font-size: 2rem;
    color: var(--primary-color);
}

.user-info {
    display: flex;
    align-items: center;
    gap: 15px;
}

.btn-logout {
    padding: 8px 16px;
    background: var(--danger-color);
    color: white;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    font-size: 0.9rem;
    transition: all 0.3s;
}

.btn-logout:hover {
    background: #dc2626;
    transform: translateY(-2px);
}

/* Auth Box - Login/Register */
.auth-box {
    max-width: 500px;
    margin: 50px auto;
    background: rgba(30, 41, 59, 0.9);
    padding: 40px;
    border-radius: 15px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(10px);
}

.auth-box h1 {
    text-align: center;
    font-size: 3rem;
    color: var(--primary-color);
    margin-bottom: 10px;
}

.subtitle {
    text-align: center;
    color: var(--gray-text);
    margin-bottom: 30px;
}

.form-container {
    display: none;
}

.form-container.active {
    display: block;
    animation: fadeIn 0.3s;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
}

.form-group {
    margin-bottom: 20px;
}

.form-group label {
    display: block;
    margin-bottom: 8px;
    color: var(--light-text);
    font-weight: 500;
}

.form-group input {
    width: 100%;
    padding: 12px;
    background: rgba(15, 23, 42, 0.8);
    border: 2px solid rgba(100, 116, 139, 0.3);
    border-radius: 8px;
    color: var(--light-text);
    font-size: 1rem;
    transition: all 0.3s;
}

.form-group input:focus {
    outline: none;
    border-color: var(--primary-color);
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 15px;
}

hr {
    margin: 25px 0;
    border: none;
    border-top: 1px solid rgba(100, 116, 139, 0.3);
}

h3 {
    margin-bottom: 15px;
    color: var(--primary-color);
}

/* Buttons */
.btn {
    width: 100%;
    padding: 14px;
    border: none;
    border-radius: 8px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s;
    margin-top: 10px;
}

.btn-primary {
    background: var(--primary-color);
    color: white;
}

.btn-primary:hover {
    background: #1d4ed8;
    transform: translateY(-2px);
    box-shadow: 0 10px 25px rgba(37, 99, 235, 0.3);
}

.btn-success {
    background: var(--success-color);
    color: white;
}

.btn-success:hover {
    background: #059669;
    transform: translateY(-2px);
    box-shadow: 0 10px 25px rgba(16, 185, 129, 0.3);
}

.btn-secondary {
    background: rgba(100, 116, 139, 0.5);
    color: white;
}

.btn-secondary:hover {
    background: rgba(100, 116, 139, 0.7);
}

.switch-form {
    text-align: center;
    margin-top: 20px;
    color: var(--gray-text);
}

.switch-form a {
    color: var(--primary-color);
    text-decoration: none;
    font-weight: 600;
}

.switch-form a:hover {
    text-decoration: underline;
}

/* Main Content Layout */
.main-content {
    display: grid;
    grid-template-columns: 350px 1fr;
    gap: 30px;
}

/* Side Panel */
.side-panel {
    background: rgba(30, 41, 59, 0.8);
    padding: 25px;
    border-radius: 15px;
    backdrop-filter: blur(10px);
    height: fit-content;
}

.vehicle-info, .booking-form, .legend {
    margin-bottom: 25px;
    padding-bottom: 25px;
    border-bottom: 1px solid rgba(100, 116, 139, 0.3);
}

.vehicle-info:last-child, .legend:last-child {
    border-bottom: none;
}

.vehicle-info h3, .booking-form h3, .legend h4 {
    color: var(--primary-color);
    margin-bottom: 15px;
}

.vehicle-detail {
    display: flex;
    justify-content: space-between;
    padding: 8px 0;
    color: var(--gray-text);
}

.vehicle-detail strong {
    color: var(--light-text);
}

/* Booking Form */
.selected-spot-info {
    background: rgba(59, 130, 246, 0.1);
    border-left: 4px solid var(--primary-color);
    padding: 15px;
    margin-bottom: 20px;
    border-radius: 5px;
}

.cost-summary {
    background: rgba(15, 23, 42, 0.5);
    padding: 15px;
    border-radius: 8px;
    margin: 20px 0;
}

.cost-row {
    display: flex;
    justify-content: space-between;
    padding: 8px 0;
    color: var(--gray-text);
}

.cost-row.total {
    border-top: 2px solid rgba(100, 116, 139, 0.3);
    margin-top: 10px;
    padding-top: 15px;
    font-size: 1.1rem;
    color: var(--light-text);
}

/* Legend */
.legend-item {
    display: flex;
    align-items: center;
    gap: 10px;
    margin: 10px 0;
}

.spot-legend {
    width: 40px;
    height: 40px;
    border-radius: 8px;
    border: 2px solid rgba(255, 255, 255, 0.1);
}

.spot-legend.available {
    background: var(--available-color);
}

.spot-legend.occupied {
    background: var(--occupied-color);
}

.spot-legend.selected {
    background: var(--selected-color);
    border-color: white;
}

/* Parking Map */
.parking-map {
    background: rgba(30, 41, 59, 0.8);
    padding: 30px;
    border-radius: 15px;
    backdrop-filter: blur(10px);
}

.floor-section {
    margin-bottom: 40px;
}

.floor-section h2 {
    color: var(--primary-color);
    margin-bottom: 20px;
    font-size: 1.8rem;
    border-bottom: 3px solid var(--primary-color);
    padding-bottom: 10px;
}

.spots-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 15px;
}

.spot {
    aspect-ratio: 1;
    border-radius: 10px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    cursor: pointer;
    transition: all 0.3s;
    border: 3px solid rgba(255, 255, 255, 0.1);
    font-weight: bold;
    position: relative;
}

.spot:hover {
    transform: translateY(-5px);
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
}

.spot.available {
    background: linear-gradient(135deg, #22c55e 0%, #16a34a 100%);
}

.spot.occupied {
    background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%);
    cursor: not-allowed;
    opacity: 0.6;
}

.spot.occupied:hover {
    transform: none;
}

.spot.selected {
    background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);
    border-color: white;
    box-shadow: 0 0 20px rgba(59, 130, 246, 0.5);
}

.spot-number {
    font-size: 1.5rem;
    margin-bottom: 5px;
}

.spot-type {
    font-size: 0.7rem;
    opacity: 0.8;
    text-transform: uppercase;
}

/* Message Box */
.message-box {
    position: fixed;
    top: 20px;
    right: 20px;
    min-width: 300px;
    padding: 15px 20px;
    border-radius: 10px;
    color: white;
    font-weight: 500;
    display: none;
    animation: slideIn 0.3s;
    z-index: 1000;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
}

@keyframes slideIn {
    from { transform: translateX(400px); opacity: 0; }
    to { transform: translateX(0); opacity: 1; }
}

.message-box.success {
    background: var(--success-color);
    display: block;
}

.message-box.error {
    background: var(--danger-color);
    display: block;
}

.message-box.info {
    background: var(--primary-color);
    display: block;
}

/* Responsive */
@media (max-width: 1024px) {
    .main-content {
        grid-template-columns: 1fr;
    }

    .spots-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

@media (max-width: 768px) {
    .auth-box {
        padding: 25px;
        margin: 20px;
    }

    .form-row {
        grid-template-columns: 1fr;
    }

    .spots-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}
