{"content": "const express = require('express');
const router = express.Router();
const bcrypt = require('bcryptjs');
const pool = require('../config/database');

// ═══════════════════════════════════════════════════════════════
// AUTENTICACIÓN DE ADMINISTRADOR
// ═══════════════════════════════════════════════════════════════

// Verificar si ya existe un administrador
router.get('/check-admin', async (req, res) => {
  try {
    const result = await pool.query('SELECT COUNT(*) as total FROM Administradores');
    const hayAdmin = parseInt(result.rows[0].total) > 0;

    res.json({ 
      existe_admin: hayAdmin,
      mensaje: hayAdmin ? 'Ya existe un administrador' : 'No hay administradores, debe registrarse'
    });
  } catch (error) {
    console.error('Error al verificar admin:', error);
    res.status(500).json({ error: 'Error al verificar administrador' });
  }
});

// Registro de administrador (solo si no existe ninguno)
router.post('/register', async (req, res) => {
  try {
    const { username, password, nombre_completo } = req.body;

    if (!username || !password || !nombre_completo) {
      return res.status(400).json({ error: 'Todos los campos son requeridos' });
    }

    if (password.length < 6) {
      return res.status(400).json({ error: 'La contraseña debe tener al menos 6 caracteres' });
    }

    // Verificar que no exista ya un admin
    const checkAdmin = await pool.query('SELECT COUNT(*) as total FROM Administradores');
    if (parseInt(checkAdmin.rows[0].total) > 0) {
      return res.status(403).json({ error: 'Ya existe un administrador registrado' });
    }

    // Hashear contraseña
    const password_hash = await bcrypt.hash(password, 10);

    // Insertar administrador
    const result = await pool.query(
      'INSERT INTO Administradores (username, password_hash, nombre_completo) VALUES ($1, $2, $3) RETURNING id_admin, username, nombre_completo, fecha_registro',
      [username, password_hash, nombre_completo]
    );

    res.status(201).json({
      message: 'Administrador registrado exitosamente',
      admin: result.rows[0]
    });

  } catch (error) {
    console.error('Error en registro de admin:', error);
    if (error.code === '23505') { // Violación de unique constraint
      res.status(400).json({ error: 'El nombre de usuario ya existe' });
    } else {
      res.status(500).json({ error: 'Error al registrar administrador' });
    }
  }
});

// Login de administrador
router.post('/login', async (req, res) => {
  try {
    const { username, password } = req.body;

    if (!username || !password) {
      return res.status(400).json({ error: 'Usuario y contraseña requeridos' });
    }

    // Buscar admin
    const result = await pool.query(
      'SELECT * FROM Administradores WHERE username = $1',
      [username]
    );

    if (result.rows.length === 0) {
      return res.status(401).json({ error: 'Credenciales inválidas' });
    }

    const admin = result.rows[0];

    // Verificar contraseña
    const passwordValida = await bcrypt.compare(password, admin.password_hash);

    if (!passwordValida) {
      return res.status(401).json({ error: 'Credenciales inválidas' });
    }

    // Actualizar último acceso
    await pool.query(
      'UPDATE Administradores SET ultimo_acceso = CURRENT_TIMESTAMP WHERE id_admin = $1',
      [admin.id_admin]
    );

    // No enviar el password_hash
    delete admin.password_hash;

    res.json({
      message: 'Login exitoso',
      admin: admin
    });

  } catch (error) {
    console.error('Error en login de admin:', error);
    res.status(500).json({ error: 'Error al iniciar sesión' });
  }
});

// ═══════════════════════════════════════════════════════════════
// CRUD DE USUARIOS
// ═══════════════════════════════════════════════════════════════

// Obtener todos los usuarios con sus vehículos
router.get('/usuarios', async (req, res) => {
  try {
    const result = await pool.query(`
      SELECT 
        u.id_usuario,
        u.nombre,
        u.apellido,
        u.email,
        u.fecha_registro,
        json_agg(
          json_build_object(
            'id_vehiculo', v.id_vehiculo,
            'placa', v.placa,
            'marca', v.marca,
            'modelo', v.modelo,
            'color', v.color
          )
        ) FILTER (WHERE v.id_vehiculo IS NOT NULL) as vehiculos
      FROM Usuarios u
      LEFT JOIN Vehiculos v ON u.id_usuario = v.id_usuario
      GROUP BY u.id_usuario
      ORDER BY u.fecha_registro DESC
    `);

    res.json(result.rows);
  } catch (error) {
    console.error('Error al obtener usuarios:', error);
    res.status(500).json({ error: 'Error al obtener usuarios' });
