    }

    const password_hash = await bcrypt.hash(password, 10);

    const result = await pool.query(
      'INSERT INTO Usuarios (nombre, apellido, email, password_hash) VALUES ($1, $2, $3, $4) RETURNING id_usuario, nombre, apellido, email, fecha_registro',
