      'UPDATE Usuarios SET nombre = $1, apellido = $2, email = $3 WHERE id_usuario = $4 RETURNING *',
      [nombre, apellido, email, id]
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Usuario no encontrado' });
