// Finalizar ticket manualmente (forzar salida)
router.patch('/tickets/:id/finalizar', async (req, res) => {
  const client = await pool.connect();
  try {
    const { id } = req.params;
    const { monto_cobrado } = req.body;

    await client.query('BEGIN');

    // Obtener info del ticket
    const ticketInfo = await client.query(
      'SELECT id_cajon, estado FROM TicketsEstancia WHERE id_ticket = $1',
      [id]
    );

    if (ticketInfo.rows.length === 0) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'Ticket no encontrado' });
    }

    const ticket = ticketInfo.rows[0];

    // Actualizar ticket
    await client.query(
      'UPDATE TicketsEstancia SET fecha_hora_salida = CURRENT_TIMESTAMP, monto_cobrado = $1, estado = $2 WHERE id_ticket = $3',
      [monto_cobrado || 0, 'PAGADO', id]
    );

    // Liberar cajón
    await client.query(
      'UPDATE CajonesEstacionamiento SET estado = $1 WHERE id_cajon = $2',
      ['Disponible', ticket.id_cajon]
    );

    await client.query('COMMIT');

    res.json({
      message: 'Ticket finalizado exitosamente'
    });

  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Error al finalizar ticket:', error);
    res.status(500).json({ error: 'Error al finalizar ticket' });
  } finally {
    client.release();
  }
});

// Eliminar ticket
router.delete('/tickets/:id', async (req, res) => {
  const client = await pool.connect();
  try {
    const { id } = req.params;

    await client.query('BEGIN');

    // Obtener cajón antes de eliminar
    const ticketInfo = await client.query(
      'SELECT id_cajon, codigo_acceso FROM TicketsEstancia WHERE id_ticket = $1',
      [id]
    );

    if (ticketInfo.rows.length === 0) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'Ticket no encontrado' });
    }

    // Liberar el cajón
    await client.query(
      'UPDATE CajonesEstacionamiento SET estado = $1 WHERE id_cajon = $2',
      ['Disponible', ticketInfo.rows[0].id_cajon]
    );

    // Eliminar ticket
    await client.query('DELETE FROM TicketsEstancia WHERE id_ticket = $1', [id]);

    await client.query('COMMIT');

    res.json({
      message: `Ticket ${ticketInfo.rows[0].codigo_acceso} eliminado exitosamente`
    });

  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Error al eliminar ticket:', error);
    res.status(500).json({ error: 'Error al eliminar ticket' });
  } finally {
    client.release();
  }
});

