      [descripcion, costo_por_hora, id]
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Tarifa no encontrada' });
    }

    res.json({
      message: 'Tarifa actualizada exitosamente',
      tarifa: result.rows[0]
    });

  } catch (error) {
    console.error('Error al actualizar tarifa:', error);
    res.status(500).json({ error: 'Error al actualizar tarifa' });
  }
});

// Eliminar tarifa
router.delete('/tarifas/:id', async (req, res) => {
  try {
    const { id } = req.params;

    // Verificar que no haya cajones usando esta tarifa
    const checkCajones = await pool.query(
      'SELECT COUNT(*) as total FROM CajonesEstacionamiento WHERE id_tarifa = $1',
      [id]
    );

    if (parseInt(checkCajones.rows[0].total) > 0) {
      return res.status(400).json({ 
        error: 'No se puede eliminar la tarifa porque hay cajones que la usan' 
      });
    }

    const result = await pool.query(
      'DELETE FROM Tarifas WHERE id_tarifa = $1 RETURNING descripcion',
      [id]
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Tarifa no encontrada' });
    }

    res.json({
      message: `Tarifa ${result.rows[0].descripcion} eliminada exitosamente`
    });

  } catch (error) {
    console.error('Error al eliminar tarifa:', error);
    res.status(500).json({ error: 'Error al eliminar tarifa' });
  }
});

// ═══════════════════════════════════════════════════════════════
// ESTADÍSTICAS
// ═══════════════════════════════════════════════════════════════

router.get('/stats', async (req, res) => {
  try {
    const stats = {};

    // Total de usuarios
    const usuarios = await pool.query('SELECT COUNT(*) as total FROM Usuarios');
    stats.total_usuarios = parseInt(usuarios.rows[0].total);

    // Total de vehículos
    const vehiculos = await pool.query('SELECT COUNT(*) as total FROM Vehiculos');
    stats.total_vehiculos = parseInt(vehiculos.rows[0].total);

    // Cajones por estado
    const cajones = await pool.query(`
      SELECT 
        COUNT(*) as total,
        SUM(CASE WHEN estado = 'Disponible' THEN 1 ELSE 0 END) as disponibles,
        SUM(CASE WHEN estado = 'Ocupado' THEN 1 ELSE 0 END) as ocupados,
        SUM(CASE WHEN estado = 'Mantenimiento' THEN 1 ELSE 0 END) as mantenimiento
      FROM CajonesEstacionamiento
    `);
    stats.cajones = cajones.rows[0];

    // Tickets activos
    const ticketsActivos = await pool.query(
      'SELECT COUNT(*) as total FROM TicketsEstancia WHERE estado = $1',
      ['ACTIVO']
    );
    stats.tickets_activos = parseInt(ticketsActivos.rows[0].total);

    // Total recaudado
    const recaudado = await pool.query(
      'SELECT COALESCE(SUM(monto_cobrado), 0) as total FROM TicketsEstancia WHERE estado = $1',
      ['PAGADO']
    );
    stats.total_recaudado = parseFloat(recaudado.rows[0].total);

    res.json(stats);

  } catch (error) {
    console.error('Error al obtener estadísticas:', error);
    res.status(500).json({ error: 'Error al obtener estadísticas' });
  }
});

module.exports = router;
