{"content": "/* Estilos adicionales para el Panel de Administración */

.info-text {
    background: rgba(245, 158, 11, 0.1);
    border-left: 4px solid var(--warning-color);
    padding: 12px;
    margin: 15px 0;
    border-radius: 5px;
    color: var(--warning-color);
}

/* Admin Panel Layout */
.admin-panel {
    min-height: 100vh;
    background: linear-gradient(135deg, var(--darker-bg) 0%, var(--dark-bg) 100%);
    padding: 0;
}

.admin-header {
    background: rgba(30, 41, 59, 0.9);
    padding: 20px 40px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 2px solid var(--primary-color);
    backdrop-filter: blur(10px);
}

.header-left h1 {
    font-size: 1.8rem;
    color: var(--primary-color);
    margin-bottom: 5px;
}

.admin-name {
    color: var(--gray-text);
    font-size: 0.9rem;
}

/* Stats Cards */
.stats-container {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 20px;
    padding: 30px 40px;
}

.stat-card {
    background: rgba(30, 41, 59, 0.8);
    padding: 25px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    gap: 20px;
    backdrop-filter: blur(10px);
    border: 1px solid rgba(100, 116, 139, 0.2);
    transition: all 0.3s;
}

.stat-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
    border-color: var(--primary-color);
}

.stat-icon {
    font-size: 3rem;
}

.stat-info h3 {
    font-size: 2rem;
    color: var(--light-text);
    margin: 0;
}

.stat-info p {
    color: var(--gray-text);
    margin: 5px 0 0 0;
    font-size: 0.9rem;
}

/* Tabs */
.tabs {
    display: flex;
    gap: 10px;
    padding: 0 40px;
    background: rgba(15, 23, 42, 0.5);
    border-bottom: 2px solid rgba(100, 116, 139, 0.2);
}

.tab-btn {
    padding: 15px 25px;
    background: transparent;
    border: none;
    color: var(--gray-text);
    cursor: pointer;
    font-size: 1rem;
    font-weight: 600;
    transition: all 0.3s;
    border-bottom: 3px solid transparent;
}

.tab-btn:hover {
    color: var(--light-text);
    background: rgba(100, 116, 139, 0.1);
}

.tab-btn.active {
    color: var(--primary-color);
    border-bottom-color: var(--primary-color);
}

/* Content Area */
.admin-content {
    padding: 30px 40px;
}

.tab-content {
    display: none;
}

.tab-content.active {
    display: block;
    animation: fadeIn 0.3s;
}

.content-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 25px;
}

.content-header h2 {
    color: var(--light-text);
    font-size: 1.8rem;
}

/* Tables */
.table-container {
    background: rgba(30, 41, 59, 0.8);
    border-radius: 12px;
    overflow: hidden;
    backdrop-filter: blur(10px);
}

table {
    width: 100%;
    border-collapse: collapse;
}

thead {
    background: rgba(15, 23, 42, 0.9);
}

thead th {
    padding: 15px;
    text-align: left;
    color: var(--light-text);
    font-weight: 600;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

tbody tr {
    border-bottom: 1px solid rgba(100, 116, 139, 0.2);
    transition: all 0.2s;
}

tbody tr:hover {
    background: rgba(100, 116, 139, 0.1);
}

tbody td {
    padding: 15px;
    color: var(--light-text);
}

/* Action Buttons */
.action-buttons {
    display: flex;
    gap: 8px;
}

.btn-small {
    padding: 6px 12px;
    font-size: 0.85rem;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    transition: all 0.2s;
    font-weight: 600;
}

.btn-edit {
    background: var(--primary-color);
    color: white;
}

.btn-edit:hover {
    background: #1d4ed8;
}

.btn-delete {
    background: var(--danger-color);
    color: white;
}

.btn-delete:hover {
    background: #dc2626;
}

.btn-status {
    background: var(--warning-color);
    color: white;
}

.btn-status:hover {
    background: #d97706;
}

.btn-finalize {
    background: var(--success-color);
    color: white;
}

.btn-finalize:hover {
    background: #059669;
}

/* Status Badges */
.status-badge {
    padding: 5px 12px;
    border-radius: 20px;
    font-size: 0.8rem;
    font-weight: 600;
    text-transform: uppercase;
}

.status-disponible {
    background: rgba(34, 197, 94, 0.2);
    color: #22c55e;
    border: 1px solid #22c55e;
}

.status-ocupado {
    background: rgba(239, 68, 68, 0.2);
    color: #ef4444;
    border: 1px solid #ef4444;
}

.status-mantenimiento {
    background: rgba(245, 158, 11, 0.2);
    color: #f59e0b;
    border: 1px solid #f59e0b;
}

.status-activo {
    background: rgba(59, 130, 246, 0.2);
    color: #3b82f6;
    border: 1px solid #3b82f6;
}

.status-pagado {
    background: rgba(34, 197, 94, 0.2);
    color: #22c55e;
    border: 1px solid #22c55e;
}

/* Modal */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.7);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 1000;
    animation: fadeIn 0.3s;
}

.modal {
    background: rgba(30, 41, 59, 0.98);
    border-radius: 15px;
    padding: 30px;
    max-width: 500px;
    width: 90%;
    max-height: 90vh;
    overflow-y: auto;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(10px);
}

.modal h2 {
    color: var(--primary-color);
    margin-bottom: 20px;
}

.modal-buttons {
    display: flex;
    gap: 10px;
    justify-content: flex-end;
    margin-top: 20px;
}

/* Vehiculos Badge */
.vehiculos-badge {
    background: rgba(59, 130, 246, 0.2);
    color: var(--primary-color);
    padding: 3px 10px;
    border-radius: 15px;
    font-size: 0.85rem;
    font-weight: 600;
}

/* Empty State */
.empty-state {
    text-align: center;
    padding: 60px 20px;
    color: var(--gray-text);
}

.empty-state-icon {
    font-size: 4rem;
    margin-bottom: 15px;
}

/* Loading Spinner */
.loading {
    text-align: center;
    padding: 40px;
    color: var(--gray-text);
}

.loading::after {
    content: "⏳";
    font-size: 3rem;
    animation: spin 2s linear infinite;
}

@keyframes spin {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
}

/* Responsive */
@media (max-width: 1024px) {
    .admin-header,
    .tabs,
    .admin-content {
        padding-left: 20px;
        padding-right: 20px;
    }

    .stats-container {
        padding: 20px;
        grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    }

    .tabs {
        overflow-x: auto;
        flex-wrap: nowrap;
    }
}

@media (max-width: 768px) {
    .content-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 15px;
    }

    .table-container {
        overflow-x: auto;
    }

    table {
        min-width: 800px;
    }
}
